(function () {
  var panel = document.querySelector('[data-crays-consent-panel]');
  if (!panel) return;
  var storageKey = 'crays-cookie-consent';
  function openPanel() {
    panel.hidden = false;
    panel.classList.add('is-open');
  }
  function closePanel(value) {
    if (value) {
      try { window.localStorage.setItem(storageKey, value); } catch (error) {}
    }
    panel.classList.remove('is-open');
    panel.hidden = true;
  }
  document.querySelectorAll('[data-crays-consent-open]').forEach(function (button) {
    button.addEventListener('click', openPanel);
  });
  panel.querySelectorAll('[data-crays-consent-close]').forEach(function (button) {
    button.addEventListener('click', function () { closePanel(button.getAttribute('data-crays-consent-close')); });
  });
})();

(function () {
  var page = document.querySelector('main.crays-finance-page');
  if (!page) return;
  var thesis = page.querySelector('section.crays-finance-section--thesis');
  var imageStrip = page.querySelector('section.crays-finance-image-strip');
  var metrics = page.querySelector('section.crays-finance-hero .crays-finance-hero__metrics');
  if (!thesis || page.querySelector('#finance-priorities')) return;
  if (metrics) metrics.remove();
  var section = document.createElement('section');
  section.className = 'crays-finance-section crays-finance-priorities-v2';
  section.id = 'finance-priorities';
