(function () {
  const main = document.querySelector("main.crays-finance-page");
  if (!main) return;

  const replacements = [
    { src: "/assets/stock-lifestyle/crays-finance-use-hospitality.jpg", alt: "Hospitality demand inside the Crays finance ecosystem" },
    { src: "/assets/stock-lifestyle/crays-finance-use-real-world-assets.jpg", alt: "Real-world assets connected to Crays finance demand" },
