    { src: "/assets/stock-lifestyle/crays-finance-intro-association-capital.jpg", alt: "Association capital planning for Crays finance" },
    { src: "/assets/stock-lifestyle/crays-finance-intro-association-governance.jpg", alt: "Association governance for finance structures" },
