    { src: "/assets/stock-lifestyle/crays-hospitality-demand-sailing-community.jpg", alt: "Sailing community creating lifestyle demand" },
    { src: "/assets/stock-lifestyle/crays-real-reference-yacht-demand.jpg", alt: "Yacht demand connected to real asset usage" },
    { src: "/assets/stock-lifestyle/crays-real-reference-rooftop-pool.jpg", alt: "Rooftop hospitality usage connected to finance demand" }
  ];

  const used = new Set();
  let nextReplacement = 0;
  function pathOf(src) {
    try {
      return new URL(src, window.location.origin).pathname;
    } catch (error) {
      return src;
    }
  }

  Array.prototype.slice.call(main.querySelectorAll("img[src]")).forEach(function (image) {
